class EventBus {
  constructor() {
    this.listeners = {};
  }

  on(event, fn) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(fn);
  }

  emit(event, ...args) {
    if (!this.listeners[event]) {
      return 0;
    }

    this.listeners[event].forEach(fn => fn(...args));
    return this.listeners[event].length;
  }
}

