      for (let k = 0; k < cols; k++) {
        if (k !== j) {
          row.push(m[i][k]);
        }
      }
      minor.push(row);
    }

    // Calculate cofactor and add to determinant
    const sign = (j % 2 === 0) ? 1 : -1;
    det += sign * m[0][j] * determinant(minor);
